import { BrowserRouter, Route, Routes } from "react-router-dom";
import Home from "./components/Home";
import { Container } from "reactstrap";
import Login from "./components/Login";
import Registration from "./components/Registration";
import Logout from "./components/Logout";
import { ToastContainer } from "react-toastify";
import CustomNav from "./components/CustomsNav";
import ProductView from "./components/ProductView";
import Basket from "./components/basket";
import { userData } from "./helpers";

function App() {
  const {basket , addToBasket} = useBasket
  const { jwt } = userData();
  const isLoggedIn = !!jwt;

  return (
    <Container>


      <BrowserRouter>
      <CustomNav basketItems={0} isLoggedIn={isLoggedIn} />

        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/login" element={<Login />} />
          <Route path="/logout" element={<Logout />} />
          <Route path="/registration" element={<Registration />} />
          <Route path="/product-details/:documentId" element={<ProductView  addToBasket= {addToBasket}/>} />
          <Route path="/basket" element={<Basket basket={[]}/>} />
        </Routes>
        <ToastContainer />
      </BrowserRouter>
    </Container>
  );
}

export default App;
